class.description:
Classe statique (non instanciable) : appeler directement [code]SaveManager.save(...)[/code]. Chaque opération utilise le [member SaveData.system_id] comme nom de fichier et la [SaveConfig] passée en argument pour le dossier et l'extension ; en général, celle du [SaveData] lui-même.
Le résultat est écrit dans la console (succès en vert, échec en rouge, sauvegarde absente en jaune) avec l'icône du module.
[codeblock]
var options := SaveData.new()
options.system_id = "options"
options.is_encrypted = false

func enregistrer(volume: float) -> void:
	options.data["volume"] = volume
	SaveManager.save(options, options.file_config)

func charger() -> float:
	var relu := SaveManager.load(options, options.file_config)
	return relu.data.get("volume", 1.0) if relu else 1.0
[/codeblock]
